// ✅ Validador tolerante + normalización

const draft = $json ?? {};
const errors = [];

// Helpers
const clamp = (s = '', n = 160) =>
  String(s).trim().length <= n
    ? String(s).trim()
    : String(s).trim().slice(0, n - 1).trimEnd() + '…';

const pickFirst = (...vals) => {
  for (const v of vals) {
    if (v !== undefined && v !== null) {
      const s = String(v).trim();
      if (s) return s;
    }
  }
  return '';
};

// 1) Normalizar título y metas
const title = pickFirst(
  draft.title,
  draft.article_title,
  draft.idea_title
);

const metaTitle = pickFirst(
  draft.meta_title,
  title && clamp(title, 60)
);

const metaDescription = pickFirst(
  draft.meta_description,
  draft.excerpt,
  draft.resume,
  draft.summary
);

// 2) Consolidar contenido → content_html
// Si ya traes HTML úsalo; si no, usa content/article_text/raw_markdown como fallback.
// (Si necesitas convertir Markdown a HTML, hazlo en un nodo aparte)
const contentHtml = pickFirst(
  draft.content_html,
  draft.content,
  draft.article_text,
  draft.content_markdown,
  draft.raw_markdown
);

// 3) Validaciones mínimas
if (!title) {
  errors.push('Falta título del artículo');
}
if (!contentHtml) {
  errors.push('Falta contenido HTML');
}
if (!metaTitle) {
  errors.push('Falta meta título');
}
// La meta description puede ser opcional; si quieres exigirla, descomenta:
// if (!metaDescription) errors.push('Falta meta descripción');

// 4) Lanzar error si corresponde
if (errors.length) {
  throw new Error(`Validación fallida: ${errors.join('; ')}`);
}

// 5) Salida normalizada (mantén todo lo original + campos asegurados)
return [{
  json: {
    ...draft,
    title,
    meta_title: metaTitle,
    meta_description: metaDescription,
    // Campo estandarizado que usarán los nodos de publicación
    content_html: contentHtml
  }
}];

// ===== 1. Entradas base =====
const draft = $json;
const body = $items('Webhook', 0)[0].json.body || {};

// ===== 2. Credenciales / config WP =====
const wpAuthHeader =
  body.wordpress_auth_header ||
  draft.wordpress_auth_header ||
  $env.WORDPRESS_AUTH_HEADER;

const wpNonce =
  body.wordpress_nonce ||
  draft.wordpress_nonce ||
  $env.WORDPRESS_NONCE;

if (!wpAuthHeader) {
  throw new Error('Falta wordpress_auth_header para autenticación');
}

// Endpoint oficial limpio
const wordpressPostsEndpoint = 'https://larabs.pe/wp-json/wp/v2/posts';

// ===== 3. Helpers =====

// (A) quitar bloque de "frontmatter" o cabecera SEO
// Reglas:
// - si el texto empieza con "---", quitamos todo hasta la siguiente línea con el primer heading real
// - si no empieza con "---" pero las primeras líneas tienen "Meta Title:", "Meta Description:", "Tags:",
//   también las removemos manualmente
function stripFrontmatterOrSeoHeader(mdRaw) {
  if (!mdRaw) return '';
  let md = mdRaw.trim();

  // Caso 1: bloque tipo frontmatter con '---'
  if (md.startsWith('---')) {
    const lines = md.split('\n');
    let startIndex = 0;
    for (let i = 0; i < lines.length; i++) {
      const t = lines[i].trim();
      if (/^#\s+/.test(t) || /^##\s+/.test(t)) {
        startIndex = i;
        break;
      }
    }
    md = lines.slice(startIndex).join('\n').trim();
  } else {
    // Caso 2: cabecera SEO suelta sin las rayas ---
    // Ejemplo:
    // Meta Title: ...
    // Meta Description: ...
    // Tags: ...
    // # Título real
    const lines = md.split('\n');
    let firstHeadingIndex = 0;
    for (let i = 0; i < lines.length; i++) {
      const t = lines[i].trim();
      if (/^#\s+/.test(t) || /^##\s+/.test(t)) {
        firstHeadingIndex = i;
        break;
      }
    }
    md = lines.slice(firstHeadingIndex).join('\n').trim();
  }

  return md;
}

// (B) convertir markdown -> HTML básico
// - "# Título" => <h1>...</h1>
// - "## Subtítulo" => <h2>...</h2>
// - "### ..." => <h3>...</h3>
// - líneas normales => <p>...</p>
function markdownToBasicHtml(md) {
  if (!md) return '';

  const lines = md.split('\n');

  let sawMainHeading = false;

  const htmlLines = lines.map(line => {
    const t = line.trim();

    // Si la línea empieza con "# " (nivel h1 en markdown)
    if (/^#\s+/.test(t)) {
      if (!sawMainHeading) {
        // Primera vez que vemos un H1 → NO lo incluimos en el contenido
        sawMainHeading = true;
        return '';
      } else {
        // Si aparece otro "# ..." después del primero,
        // lo tratamos como subtítulo h2
        return '<h2>' + t.replace(/^#\s+/, '') + '</h2>';
      }
    }

    if (/^##\s+/.test(t)) {
      return '<h2>' + t.replace(/^##\s+/, '') + '</h2>';
    }
    if (/^###\s+/.test(t)) {
      return '<h3>' + t.replace(/^###\s+/, '') + '</h3>';
    }

    if (t === '') {
      return '';
    }

    return '<p>' + t + '</p>';
  });

  return htmlLines.filter(l => l !== '').join('\n');
}

// ===== 4. Preparar el cuerpo del artículo =====
// En tu BD, content_html en realidad es markdown (lo vimos con "# ..."), así que lo tratamos como markdown fuente.
const markdownSource =
  (draft.content_html && draft.content_html.trim().length > 0
    ? draft.content_html
    : draft.content_markdown || ''
  );

// 1. Quitamos cabecera de SEO tipo "Meta Title / Meta Description / Tags"
const cleanMarkdown = stripFrontmatterOrSeoHeader(markdownSource);

// 2. Convertimos ese markdown ya limpio a HTML básico
let articleHtml = markdownToBasicHtml(cleanMarkdown);

// fallback defensivo
if (!articleHtml || articleHtml.trim().length === 0) {
  articleHtml = '<p>(Contenido no disponible)</p>';
}

// ===== 4.1 Inyectar imagen destacada al inicio del contenido =====
// Si tenemos featured_image_url, metemos un bloque <figure> antes del contenido.
// Esto asegura que el lector vea la imagen aunque todavía no tengamos featured_media asignado.
let footerImageBlock = '';

if (
  draft.featured_image_url &&
  typeof draft.featured_image_url === 'string' &&
  draft.featured_image_url.trim().length > 0
) {
  const altText =
    (draft.featured_image_alt && draft.featured_image_alt.trim().length > 0)
      ? draft.featured_image_alt.trim()
      : draft.title || 'Imagen del artículo';

  footerImageBlock = `
    <figure style="margin:2rem 0 0 0;text-align:center;">
      <img src="${draft.featured_image_url}" alt="${altText}" style="max-width:100%;height:auto;border-radius:4px;" />
    </figure>
  `;
}

// importante: imagen DESPUÉS del contenido, no antes
const finalHtml = articleHtml + '\n' + footerImageBlock;

// excerpt bonito = meta_description (para la vista de listado en algunos themes)
const safeExcerpt = draft.meta_description || '';

// ===== 5. Payload final para WP =====
const postPayload = {
  title: draft.title,
  status: body.wp_status || 'publish',
  content: finalHtml,          // <-- incluye imagen + html limpio
  excerpt: safeExcerpt,
  comment_status: 'open',
  ping_status: 'open',
};

// Featured image oficial (featured_media):
// - Si ya tenemos el ID real de WP en draft.wordpress_media_id, lo mandamos.
// - Si aún es null, simplemente no lo mandamos y WordPress no lo usará.
//   Igual la imagen ya está inline en el <content>.
/*if (draft.wordpress_media_id) {
  const parsedMediaId = parseInt(draft.wordpress_media_id, 10);
  if (!isNaN(parsedMediaId)) {
    postPayload.featured_media = parsedMediaId;
  }
} else if (
  draft.featured_image_url &&
  draft.featured_image_url.includes('wp-content')
) {
  // fallback heurístico muy débil: intenta raspar un número de la URL
  // (este fallback es opcional; lo dejamos por compatibilidad con tu versión anterior)
  const matches = draft.featured_image_url.match(/(\d+)(?=\.\w+$)/);
  if (matches && matches[1]) {
    const parsedMediaId = parseInt(matches[1], 10);
    if (!isNaN(parsedMediaId)) {
      postPayload.featured_media = parsedMediaId;
    }
  }
}*/

// Meta SEO (Yoast). Si tu WP devuelve 400/403 por campos meta bloqueados, comenta este bloque.
postPayload.meta = {
  _yoast_wpseo_title: draft.meta_title || draft.title || '',
  _yoast_wpseo_metadesc: draft.meta_description || '',
};

// Tags: dejamos solo si tienes IDs numéricos válidos
if (
  draft.tags_array &&
  Array.isArray(draft.tags_array) &&
  draft.tags_array.length > 0
) {
  const numericTags = draft.tags_array
    .map(t => parseInt(t, 10))
    .filter(n => !isNaN(n));
  if (numericTags.length > 0) {
    postPayload.tags = numericTags;
  }
}

// ===== 6. Devolver al siguiente nodo =====
return {
  json: {
    ...draft,
    wordpress_payload: postPayload,
    wordpress_posts_endpoint: wordpressPostsEndpoint,
    wordpress_auth_header: wpAuthHeader,
    wordpress_nonce: wpNonce,
    prepared_at: new Date().toISOString(),
  },
};

const wpResponse = $json;
const draftData = $items('Preparar Payload WordPress', 0)[0].json;

// Extraer datos de la respuesta de WordPress
const wpPostId = wpResponse.id || null;
const wpPostUrl = wpResponse.link || wpResponse.guid?.rendered || null;
const wpStatus = wpResponse.status || 'publish';

if (!wpPostId) {
  throw new Error('WordPress no devolvió ID del post');
}

return {
  json: {
    draft_id: draftData.draft_id,
    wordpress_post_id: wpPostId,
    wordpress_post_url: wpPostUrl,
    wordpress_status: wpStatus,
    published_at: new Date().toISOString(),
    wordpress_response: wpResponse
  }
};

const wpData = $items('Extraer Datos WordPress', 0)[0].json;
const draftUpdate = $items('Actualizar Draft', 0)[0].json;
const scheduledUpdate = $items('Actualizar Scheduled Publications', 0)[0].json || {};
const originalDraft = $items('Validar Datos', 0)[0].json;

const jobLog = {
  job_name: 'wordpress_publish',
  job_type: 'wordpress_publish',
  status: 'success',
  draft_id: wpData.draft_id,
  idea_id: originalDraft.idea_id || null,
  keyword_cluster_id: originalDraft.keyword_cluster_id || null,
  started_at: originalDraft.validation_timestamp || new Date().toISOString(),
  completed_at: new Date().toISOString(),
  duration_ms: null,
  input_data: {
    draft_id: wpData.draft_id,
    title: originalDraft.title,
    wordpress_endpoint: originalDraft.wordpress_posts_endpoint
  },
  output_data: {
    wordpress_post_id: wpData.wordpress_post_id,
    wordpress_post_url: wpData.wordpress_post_url,
    wordpress_status: wpData.wordpress_status,
    scheduled_updated: !!scheduledUpdate.id
  },
  metadata: {
    draft_title: originalDraft.title,
    project_name: originalDraft.project_name,
    word_count: originalDraft.word_count,
    has_featured_image: !!originalDraft.featured_image_url
  }
};

if (originalDraft.validation_timestamp) {
  const start = new Date(originalDraft.validation_timestamp).getTime();
  const end = new Date().getTime();
  jobLog.duration_ms = end - start;
}

return {
  json: jobLog
};

const wpData = $items('Extraer Datos WordPress', 0)[0].json;
const draftData = $items('Validar Datos', 0)[0].json;
const jobLog = $items('Insertar Job Log', 0)[0].json;

return {
  json: {
    status: 'success',
    message: 'Artículo publicado exitosamente en WordPress',
    draft_id: wpData.draft_id,
    wordpress_post_id: wpData.wordpress_post_id,
    wordpress_post_url: wpData.wordpress_post_url,
    wordpress_status: wpData.wordpress_status,
    published_at: wpData.published_at,
    job_log_id: jobLog.id,
    draft_title: draftData.title,
    project_name: draftData.project_name
  }
};

return {
  json: {
    status: 'error',
    message: 'Draft no encontrado o no está aprobado',
    draft_id: $items('Webhook', 0)[0].json.body.draft_id || null
  }
};
